<?php
declare(strict_types=1);
namespace Modules\PriyasaCore\Http\Middleware;
use Closure; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
final class IdempotencyV2 {
 public function handle(Request $request, Closure $next){if(!in_array($request->method(),['POST','PUT','PATCH','DELETE'],true))return $next($request);$key=substr((string)$request->header('Idempotency-Key'),0,191);if($key==='')return $next($request);$scope=$request->method().'|'.$request->path();$userId=optional($request->user())->id;$existing=DB::connection('priyasa')->table('priyasa_idempotency_keys')->where('key',$key)->where('scope',$scope)->where(function($q){$q->whereNull('expires_at')->orWhere('expires_at','>',now());})->first();if($existing){return response()->json(json_decode((string)$existing->response,true) ?: [],(int)$existing->status_code)->header('X-Idempotent-Replay','true');}try{DB::connection('priyasa')->table('priyasa_idempotency_keys')->insert(['key'=>$key,'scope'=>$scope,'user_id'=>$userId,'expires_at'=>now()->addHours(24),'created_at'=>now(),'updated_at'=>now()]);}catch(\Throwable $e){$existing=DB::connection('priyasa')->table('priyasa_idempotency_keys')->where('key',$key)->where('scope',$scope)->first();if($existing)return response()->json(json_decode((string)$existing->response,true) ?: [],(int)$existing->status_code)->header('X-Idempotent-Replay','true');throw $e;} $response=$next($request);$payload=$response->getData(true);DB::connection('priyasa')->table('priyasa_idempotency_keys')->where('key',$key)->where('scope',$scope)->update(['status_code'=>$response->getStatusCode(),'response'=>json_encode($payload),'updated_at'=>now()]);return $response;}
}
